#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section RectangleAngleBisector. Variable R : realType. Variables J K L M N : 'cV[R]_2. Hypothesis rect_JKLM : J != K /\ K != L /\ L != M /\ M != J /\ exists v1 v2 : 'cV[R]_2, v1 != 0 /\ v2 != 0 /\ '[v1, v2] = 0 /\ K - J = v1 /\ L - K = v2 /\ M - L = -v1 /\ J - M = -v2. Hypothesis angle_bisector_N : N \in line K M /\ exists l : R, 0 < l < 1 /\ N = K + l *: (M - K). Theorem angle_bisector_location : exists l : R, 0 < l < 1. Proof. Admitted. End
